create or replace function public.configure_character_calling(target_character_id uuid,target_secondary_class text,target_profession_id text)returns public.character_callings language plpgsql security definer set search_path=''as $$declare hero public.characters%rowtype;calling public.character_callings%rowtype;secondary_skill bigint;v_language text;rune bigint;begin
 select*into hero from public.characters where id=target_character_id and user_id=auth.uid();if hero.id is null then raise exception'character not found';end if;if not exists(select 1 from public.profession_definitions where id=target_profession_id)then raise exception'invalid profession';end if;if target_secondary_class is not null and not exists(select 1 from public.multiclass_compatibility where primary_class=hero.character_class and secondary_class=target_secondary_class)then raise exception'incompatible class';end if;
 insert into public.character_callings(character_id,user_id,secondary_class,profession_id)values(hero.id,auth.uid(),target_secondary_class,target_profession_id)returning*into calling;if target_secondary_class is not null then select id into secondary_skill from public.skill_definitions where class_id=target_secondary_class and required_level<=hero.level order by md5(hero.id::text||id::text)limit 1;insert into public.character_skills(character_id,user_id,skill_id)values(hero.id,auth.uid(),secondary_skill)on conflict do nothing;end if;
 if target_profession_id='rune_scholar'or mod(abs(pg_catalog.hashtext(hero.id::text)::bigint),100)<15 then select id into v_language from public.rune_languages order by md5(hero.id::text||id)limit 1;insert into public.character_languages values(hero.id,auth.uid(),v_language,now())on conflict do nothing;end if;if target_profession_id='rune_scholar'or mod(abs(pg_catalog.hashtext(reverse(hero.id::text))::bigint),100)<35 then select id into rune from public.rune_definitions where target_profession_id<>'rune_scholar'or language_id=v_language order by md5(id::text||hero.id::text)limit 1;insert into public.character_runes(character_id,user_id,rune_id,quantity)values(hero.id,auth.uid(),rune,1)on conflict do nothing;end if;return calling;end;$$;
